class PaymentProcessor { charge(amount:number) {} }
class InventoryManager { reserve(items:any[]) {} }
class OrderFacade {
  private payment = new PaymentProcessor();
  private inventory = new InventoryManager();
  placeOrder(order:any) {
    this.payment.charge(order.total * 0.9);
    this.inventory.reserve(order.items);
  }
}

class OrderWrapper {
  placeOrder(order:any) {
    if (order.total > 100) order.total *= 0.9; // discount rule
    this.payment.charge(order.total);
    this.inventory.reserve(order.items);
  }
}

// Version A
class OrderOrchestrator {
  placeOrder(order:any) {
    if (!this.validate(order)) throw new Error("invalid");
    this.payment.charge(order.total * 0.9); // applies discount
    this.inventory.reserve(order.items);
    this.shipping.schedule(order);
  }
}

// Version B
class OrderGateway {
  placeOrder(order:any) {
    this.orderValidationService.validate(order);
    this.paymentService.charge(order.total);
    this.inventoryService.reserve(order.items);
    this.shippingService.schedule(order);
  }
}
